import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const SRC_DIR = path.resolve(__dirname, '../web-runner/src');
const OUTPUT_BUNDLE = path.resolve(__dirname, '../web-runner/bundle.js');

const MODULE_FILES = [
  'parser.js',
  'validator.js',
  'coordinates.js',
  'layout.js',
  'styling.js',
  'assets.js',
  'elements.js',
  'runtime.js',
  'inspector.js',
  'app.js'
];

function transformModule(fileName, code) {
  let transformed = code;

  // 1. Transform imports:
  // e.g. import { a, b as c } from './parser.js'; -> const { a, b: c } = require('./parser.js');
  transformed = transformed.replace(/import\s*\{([\s\S]*?)\}\s*from\s*['"](\.[^'"]+)['"];?/g, (match, imports, modulePath) => {
    // replace ' as ' with ': ' inside destructuring
    const cjsImports = imports.replace(/\b(\w+)\s+as\s+(\w+)\b/g, '$1: $2');
    return `const {${cjsImports}} = require('${modulePath}');`;
  });

  // 2. Transform whole module imports:
  // e.g. import * as foo from './foo.js'; -> const foo = require('./foo.js');
  transformed = transformed.replace(/import\s*\*\s*as\s+(\w+)\s+from\s*['"](\.[^'"]+)['"];?/g, 'const $1 = require(\'$2\');');

  // e.g. import './foo.js'; -> require('./foo.js');
  transformed = transformed.replace(/import\s+['"](\.[^'"]+)['"];?/g, 'require(\'$1\');');

  // 3. Collect named function and class exports to attach to exports object
  const exportedIdentifiers = [];

  // Transform export function name(...) -> function name(...) + record name
  transformed = transformed.replace(/export\s+function\s+([A-Za-z0-9_$]+)/g, (match, fnName) => {
    exportedIdentifiers.push(fnName);
    return `function ${fnName}`;
  });

  // Transform export class Name -> class Name + record name
  transformed = transformed.replace(/export\s+class\s+([A-Za-z0-9_$]+)/g, (match, className) => {
    exportedIdentifiers.push(className);
    return `class ${className}`;
  });

  // Transform export const/let/var x = ... -> const/let/var x = exports.x = ...
  transformed = transformed.replace(/export\s+(const|let|var)\s+([A-Za-z0-9_$]+)\s*=/g, (match, declType, varName) => {
    exportedIdentifiers.push(varName);
    return `${declType} ${varName} = exports.${varName} =`;
  });

  // Transform standalone export { a, b as c };
  transformed = transformed.replace(/export\s*\{([\s\S]*?)\};?/g, (match, exportsList) => {
    const assignments = exportsList.split(',').map(entry => entry.trim()).filter(Boolean).map(entry => {
      const parts = entry.split(/\s+as\s+/);
      const localName = parts[0].trim();
      const exportName = (parts[1] || localName).trim();
      return `exports.${exportName} = ${localName};`;
    }).join('\n');
    return assignments;
  });

  // Append any collected function/class exports
  if (exportedIdentifiers.length > 0) {
    const exportStatements = exportedIdentifiers
      .filter((val, idx, self) => self.indexOf(val) === idx)
      .map(id => `exports.${id} = ${id};`)
      .join('\n');
    transformed += `\n/* Module Exports */\n${exportStatements}\n`;
  }

  return transformed;
}

function buildBundle() {
  console.log('Building standalone CatWeb Runner bundle...');

  const modulesObject = [];

  for (const file of MODULE_FILES) {
    const filePath = path.join(SRC_DIR, file);
    const code = fs.readFileSync(filePath, 'utf-8');
    const transformed = transformModule(file, code);

    modulesObject.push(`  './${file}': function(module, exports, require) {\n${transformed}\n  }`);
  }

  const bundleCode = `/**
 * CatWeb Web Runner & Renderer — Unified Standalone Distribution Bundle
 * 
 * Auto-generated by tools/bundle_runner.js
 * Compatible with all modern browsers via file:// protocol (CORS-free) or HTTP/HTTPS.
 * Zero external dependencies.
 */
(function() {
  'use strict';

  const installedModules = {};

  function normalizePath(id) {
    if (!id.endsWith('.js')) id += '.js';
    if (!id.startsWith('./')) id = './' + id.replace(/^\\.\\//, '');
    return id;
  }

  function require(id) {
    const resolvedId = normalizePath(id);
    if (installedModules[resolvedId]) {
      return installedModules[resolvedId].exports;
    }
    if (!modules[resolvedId]) {
      throw new Error('Module not found in CatWeb bundle: ' + id + ' (resolved as: ' + resolvedId + ')');
    }
    const module = installedModules[resolvedId] = {
      exports: {}
    };
    modules[resolvedId](module, module.exports, require);
    return module.exports;
  }

  const modules = {
${modulesObject.join(',\n\n')}
  };

  // Expose global CatWeb API on window / globalThis
  if (typeof window !== 'undefined') {
    const parser = require('./parser.js');
    const validator = require('./validator.js');
    const coordinates = require('./coordinates.js');
    const layout = require('./layout.js');
    const styling = require('./styling.js');
    const assets = require('./assets.js');
    const elements = require('./elements.js');
    const runtime = require('./runtime.js');
    const inspector = require('./inspector.js');
    const app = require('./app.js');

    window.CatWeb = {
      parser,
      validator,
      coordinates,
      layout,
      styling,
      assets,
      elements,
      runtime,
      inspector,
      app,
      // Top-level shortcuts
      parseCatWebJson: parser.parseCatWebJson,
      validateCatWeb: validator.validateCatWeb,
      renderCatWebTree: elements.renderCatWebTree,
      CatWebRuntime: runtime.CatWebRuntime,
      CatWebInspector: inspector.CatWebInspector,
      CatWebRunnerApp: app.CatWebRunnerApp,
      PRELOADED_SAMPLES: app.PRELOADED_SAMPLES
    };
  }

  // Bootstrap app
  const mainApp = require('./app.js');

  // Auto-init for browser if DOM is ready
  if (typeof window !== 'undefined' && typeof document !== 'undefined') {
    function startRunner() {
      if (!window.__CATWEB_APP__) {
        const appInstance = new mainApp.CatWebRunnerApp(document.body);
        appInstance.init();
        window.__CATWEB_APP__ = appInstance;
      }
    }

    if (document.readyState === 'loading') {
      window.addEventListener('DOMContentLoaded', startRunner);
    } else {
      startRunner();
    }
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = mainApp;
  }

  return mainApp;
})();
`;

  fs.writeFileSync(OUTPUT_BUNDLE, bundleCode, 'utf-8');
  console.log(`Bundle successfully generated at: ${OUTPUT_BUNDLE} (${(bundleCode.length / 1024).toFixed(1)} KB)`);
}

buildBundle();
